<template><view class="phone-scene"><view class="phone-intro"><text class="section-label">PRIVATE MESSAGES · 22:17</text><text class="visual-title">手机里的回声</text><AssetImage class="visual-divider" :src="uiAssets.decorations.divider" fit="contain"/><text class="visual-copy">{{description || '有些答案，藏在那些被轻轻带过的话里。'}}</text><AssetButton class="phone-continue" variant="active" @click="$emit('continue')">{{continueLabel || '收起手机，继续剧情'}}</AssetButton></view><view class="phone-device"><AssetImage class="phone-shell" :src="uiAssets.phone.shell" fit="fill"/><view class="phone-screen"><view class="status"><text>22:17</text><text>5G · 87%</text></view><view v-if="!selected" class="apps"><button role="button" tabindex="0" @keydown.enter.prevent="activateFocused" @keydown.space.prevent="activateFocused" v-for="app in apps" :key="app.name" @click="selected=app.name;contact=''"><AssetImage :src="app.icon" fit="contain"/><text>{{app.name}}</text></button></view><view v-else class="app-open"><button role="button" tabindex="0" @keydown.enter.prevent="activateFocused" @keydown.space.prevent="activateFocused" class="phone-back" @click="contact?contact='':selected=''">‹ 返回</button><text class="app-title">{{selected}}</text><view v-if="selected==='消息'&&!contact" class="message-list"><button role="button" tabindex="0" @keydown.enter.prevent="activateFocused" @keydown.space.prevent="activateFocused" v-for="c in contacts" :key="c.name" class="message" @click="contact=c.name"><AssetImage :src="c.portrait"/><view><text>{{c.name}}</text><text>{{c.preview}}</text></view><text class="message-time">{{c.time}}</text><view class="unread"/></button></view><view v-else-if="selected==='消息'" class="chat"><view class="chat-contact"><AssetImage :src="contacts.find(c=>c.name===contact)?.portrait"/><text>{{contact}}</text></view><text class="chat-time">今天 22:16</text><view class="bubble">{{contact==='爸爸'?'明天回家一趟。':'今晚的事，就当没发生。'}}</view><view class="bubble mine">{{contact==='爸爸'?'我知道了。':'婚后安排，我想再谈一次。'}}</view><